describe('Password Requirements Tooltip', () => {
  beforeEach(() => {
    cy.visit('/password-reset');
  });

  it('should display tooltip with password requirements when password is entered', () => {
    // Intercept the API call to get password validation rules
    cy.intercept('GET', '/api/password-validation-rules').as('getValidationRules');

    // Get the password input field
    cy.get('[data-testid="password-input"]').should('be.visible');

    // Type a password that meets the requirements
    cy.get('[data-testid="password-input"]').type('StrongPass123!');

    // Wait for the validation rules API call
    cy.wait('@getValidationRules');

    // Verify the tooltip is visible
    cy.get('[data-testid="password-tooltip"]').should('be.visible');

    // Verify the tooltip contains the correct message
    cy.get('[data-testid="password-tooltip"]').should('contain', 'Password must be at least 8 characters long');

    // Verify the tooltip is styled correctly
    cy.get('[data-testid="password-tooltip"]').should('have.class', 'tooltip-active');

    // Verify the password input still has focus
    cy.get('[data-testid="password-input"]').should('have.focus');
  });

  it('should hide tooltip when password is corrected to meet requirements', () => {
    // Intercept the API call to get password validation rules
    cy.intercept('GET', '/api/password-validation-rules').as('getValidationRules');

    // Get the password input field
    cy.get('[data-testid="password-input"]').should('be.visible');

    // Type a password that does not meet the requirements
    cy.get('[data-testid="password-input"]').type('Short');

    // Wait for the validation rules API call
    cy.wait('@getValidationRules');

    // Verify the tooltip is visible with an error message
    cy.get('[data-testid="password-tooltip"]').should('be.visible');
    cy.get('[data-testid="password-tooltip"]').should('contain', 'Password must be at least 8 characters long');

    // Verify the tooltip is styled correctly
    cy.get('[data-testid="password-tooltip"]').should('have.class', 'tooltip-active');

    // Verify the password input still has focus
    cy.get('[data-testid="password-input"]').should('have.focus');

    // Correct the password to meet the requirements
    cy.get('[data-testid="password-input"]').type('LongerPassword123!');

    // Wait for the validation rules API call again
    cy.wait('@getValidationRules');

    // Verify the tooltip is hidden
    cy.get('[data-testid="password-tooltip"]').should('not.exist');

    // Verify the password input no longer has focus
    cy.get('[data-testid="password-input"]').should('not.have.focus');
  });
});
